    # Fill background-colored regions completely enclosed by the outline color.
    h, w = len(grid), len(grid[0])
    outline = next(v for row in grid for v in row if v != grid[0][0])
    bg = grid[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            enclosed = True
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    enclosed = False
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == bg and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            if enclosed:
                for y, x in cells:
                    out[y][x] = 4
    return out

